/** Refresh the public, timestamped star snapshot used by site/ecosystem.html.
 *
 * `gh` authenticates locally. Only dates and counts enter the generated file;
 * stargazer identities and credentials never become site assets. A mismatch
 * between the repo total and dated events fails closed instead of inventing
 * a history line.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const owner = 'ashlrai';
const projects = [
  { repo: 'phantom', name: 'Phantom', role: 'Agent command center' },
  { repo: 'phantom-secrets', name: 'Phantom Secrets', role: 'Secret boundary' },
  { repo: 'locus', name: 'Locus', role: 'Account identity' },
  { repo: 'lexicon', name: 'Lexicon', role: 'Voice vocabulary' },
  { repo: 'ashlrcode', name: 'AshlrCode', role: 'Coding agent CLI' },
  { repo: 'morphkit', name: 'Morphkit', role: 'Web to native SwiftUI' },
];

function api(args) {
  return JSON.parse(execFileSync('gh', ['api', ...args], {
    encoding: 'utf8', maxBuffer: 32 * 1024 * 1024,
  }));
}

const asOf = new Date().toISOString();
const repos = projects.map(({ repo, name, role }) => {
  const meta = api([`repos/${owner}/${repo}`]);
  const pages = api([
    '--paginate', '--slurp', '-H', 'Accept: application/vnd.github.star+json',
    `repos/${owner}/${repo}/stargazers?per_page=100`,
  ]);
  if (meta.full_name !== `${owner}/${repo}` || meta.private || !Number.isInteger(meta.stargazers_count)) {
    throw new Error(`Invalid public repository metadata for ${repo}`);
  }
  if (!Array.isArray(pages) || !pages.every(Array.isArray)) {
    throw new Error(`Invalid dated stargazer response for ${repo}`);
  }
  const days = pages.flat().map((event) => {
    const stamp = event?.starred_at;
    if (typeof stamp !== 'string' || !/^\d{4}-\d{2}-\d{2}T/.test(stamp) || !Number.isFinite(Date.parse(stamp))) {
      throw new Error(`Missing or invalid star timestamp for ${repo}`);
    }
    return stamp.slice(0, 10);
  }).sort();
  if (days.length !== meta.stargazers_count) {
    throw new Error(`${repo}: ${meta.stargazers_count} reported stars but ${days.length} dated events; retry later`);
  }
  return { repo, name, role, url: `https://github.com/${owner}/${repo}`, stars: days.length, days };
});

const snapshot = {
  schemaVersion: 1,
  asOf,
  source: 'GitHub REST repository and dated stargazer APIs',
  scope: 'Six selected public Ashlr repositories; totals sum repo stars, not unique people.',
  repos,
};
const destination = fileURLToPath(new URL('../site/assets/star-history.js', import.meta.url));
writeFileSync(destination, `/* Generated by scripts/update-site-stars.mjs; do not edit by hand. */\nwindow.ASHLR_STAR_SNAPSHOT = ${JSON.stringify(snapshot, null, 2)};\n`);
process.stdout.write(`Wrote ${destination}: ${repos.reduce((sum, repo) => sum + repo.stars, 0)} repo stars across ${repos.length} repositories at ${asOf}\n`);
